INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10001, 1.47, 1, "2023/06/30 12:00:00", 1, "2023/09/22 14:59:59", 1, 2002, 126401, "いらっしゃいませっ♪\nキャラバンコインを使って\n買い物ができますよっ！", "クローチェ", -470.0, 0.0, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10002, 2.15, 2, "2023/06/30 12:00:00", 2, "2023/09/22 14:59:59", 1, 2002, 126401, "素敵な品が揃ってるので\nたーっくさん買っていって\nくださいねっ♪", "クローチェ", -470.0, 0.0, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10003, 0.0, 1, "2023/06/30 12:00:00", 2, "2023/09/22 14:59:59", 1, 2002, 126501, "ショップへようこそ\nキャラバンコインはこちら\nで買い物に使えますよ", "ライラエル", -470.0, 0.0, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10004, 0.0, 2, "2023/06/30 12:00:00", 1, "2023/09/22 14:59:59", 1, 2002, 126501, "こちらのショップで\n買い物をして、素敵な\n旅を楽しんでくださいね", "ライラエル", -470.0, 0.0, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10005, 0.0, 1, "2023/09/15 15:00:00", 2, "2023/12/22 14:59:59", 2, 2002, 127702, "いらっしゃいませ\nキャラバンコインを使って\nお買い物ができますよ", "リンド", -470.0, 0.0, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10006, 0.0, 2, "2023/09/15 15:00:00", 2, "2023/12/22 14:59:59", 2, 2002, 127702, "ショップの掃除は完璧です\n姫さま直営のお店として\n当然のことですから", "リンド", -470.0, 0.0, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10007, 0.0, 1, "2023/09/15 15:00:00", 1, "2023/12/22 14:59:59", 2, 2002, 127802, "ショップへようこそ\nキャラバンコインと品物を\n交換できるんで、よければ", "ヴルム", -470.0, 0.0, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10008, 6.5, 2, "2023/09/15 15:00:00", 2, "2023/12/22 14:59:59", 2, 2002, 127802, "なんで店番なんか…\nま、やりますけど\n好きな品物をどうぞ", "ヴルム", -470.0, 0.0, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10009, 0.0, 1, "2023/12/15 15:00:00", 2, "2024/03/22 14:59:59", 3, 2002, 129602, "──いらっしゃいませ\n買い物しても、いいですよ\nキャラバンコインがあれば", "アネモネ", -470.0, 0.0, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10010, 0.0, 2, "2023/12/15 15:00:00", 2, "2024/03/22 14:59:59", 3, 2002, 129602, "──もっと笑顔がほしい？\nいくらコインを積まれても\n売れない物はありますから", "アネモネ", -470.0, 0.0, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10011, 0.0, 1, "2023/12/15 15:00:00", 1, "2024/03/22 14:59:59", 3, 2002, 129701, "ようこそおいでなんし\nキャラバンコインをこちら\nで交換して進ぜんしょう", "ネフィ=ネラ", -470.0, 0.0, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10012, 6.2, 2, "2023/12/15 15:00:00", 2, "2024/03/22 14:59:59", 3, 2002, 129701, "ところで、お前さまは\nいくらで贖えるのか喃？\n──フフ、冗談でありんす", "ネフィ=ネラ", -470.0, 0.0, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10013, 3.1, 1, "2024/03/15 15:00:00", 3, "2024/06/22 14:59:59", 4, 2002, 130301, "い、いらっしゃいませっ！\n…くっ…このあたくし様が\n店番なんて…屈辱ですわっ", "カノン", -470.0, 0.0, 5);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10014, 6.15, 2, "2024/03/15 15:00:00", 3, "2024/06/22 14:59:59", 4, 2002, 130301, "あら、あたくしをご所望？\nお生憎様、そんな小銭では\n…買えちゃうんですの！？", "カノン", -470.0, 0.0, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10015, 0.0, 1, "2024/03/15 15:00:00", 2, "2024/06/22 14:59:59", 4, 2002, 130401, "いらっしゃいませ～♪\nきゃらばんこいん？を\n交換できるんだってー", "ナーナ", -470.0, 0.0, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10016, 3.35, 2, "2024/03/15 15:00:00", 2, "2024/06/22 14:59:59", 4, 2002, 130401, "甘いのくれたら、\nお礼にナーナの拾った\n松ぼっくりあげちゃうよ！", "ナーナ", -470.0, 0.0, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10017, 0.0, 1, "2024/06/15 15:00:00", 1, "2024/09/22 14:59:59", 5, 2002, 130502, "ショップへようこそ\nこの鳳凰が、皆さんに\n祝福を差し上げましょう", "ホウオウ", -470.0, 0.0, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10018, 3.18, 2, "2024/06/15 15:00:00", 2, "2024/09/22 14:59:59", 5, 2002, 130502, "ほーちゃんと呼ぶ権利は\n売っていませんよ？\n騎士さんへの、特別です！", "ホウオウ", -470.0, 0.0, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10019, 0.0, 3, "2024/06/15 15:00:00", 4, "2024/09/22 14:59:59", 5, 2002, 130503, "うﾞぇぇえんっ！まﾞだごの\n格好になっぢゃいまじだ！\n寄付をお願いじまず～っ！", "ホウオウ", -470.0, 0.0, 4);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10020, 4.9, 1, "2024/06/15 15:00:00", 1, "2024/09/22 14:59:59", 5, 2002, 123301, "おっすー♪\nなんでも交換してけー\nカリザきゅん以外で", "ネア", -470.0, 0.0, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10021, 4.8, 2, "2024/06/15 15:00:00", 1, "2024/09/22 14:59:59", 5, 2002, 123301, "ところで、騎士きゅんは\nおいくら万ルピ？\nジョーダンぬ・き・で♡", "ネア", -470.0, 0.0, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10022, 4.922, 1, "2024/09/15 15:00:00", 3, "2024/12/22 14:59:59", 6, 2002, 133301, "ケッ、なんでオレ様が店番\nなんざ…って来んなキイロ\nオレは売りモンじゃねー！", "カリザ", -470.0, 0.0, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10023, 9.638, 2, "2024/09/15 15:00:00", 3, "2024/12/22 14:59:59", 6, 2002, 133301, "い、言わなきゃダメか？\n「…いらっしゃいませ…」\nクソッ、笑うんじゃねー！", "カリザ", -470.0, 0.0, 5);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10024, 2.88, 1, "2024/09/15 15:00:00", 1, "2024/12/22 14:59:59", 6, 2002, 133401, "ショップへようこそ～\nネラさまの腹心…的な私が\n店番させていただきま～す", "ミーア", -470.0, 0.0, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10025, 4.818, 2, "2024/09/15 15:00:00", 5, "2024/12/22 14:59:59", 6, 2002, 133401, "私の抜け殻とか、\n需要ありますかね～…\nって冗談ですよ、冗談！", "ミーア", -470.0, 0.0, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10026, 1.78, 1, "2024/12/15 15:00:00", 2, "2025/03/22 14:59:59", 7, 2002, 133002, "へい、らっしゃい\nさ、騎士氏。冥土の土産は\nなにがいいですか？", "グレイス", -470.0, 0.0, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10027, 6.15, 2, "2024/12/15 15:00:00", 1, "2025/03/22 14:59:59", 7, 2002, 133002, "商品をお買い上げ毎に\nグレイスちゃんポイントを\n差し上げます。嘘ですが", "グレイス", -470.0, 0.0, 7);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10028, 4.28, 1, "2024/12/15 15:00:00", 6, "2025/03/22 14:59:59", 7, 2002, 133102, "ようこそいらっしゃいませ\n…接客とは、このような\n振舞で宜しいでしょうか？", "ヴァイオレット", -470.0, 0.0, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10029, 0.0, 2, "2024/12/15 15:00:00", 1, "2025/03/22 14:59:59", 7, 2002, 133102, "じめじめした商品は\nございませんので\n安心してお買い求め下さい", "ヴァイオレット", -470.0, 0.0, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10030, 5.53, 1, "2025/03/15 15:00:00", 2, "2025/06/23 14:59:59", 8, 2002, 136902, "いらっしゃいましぇでしゅ\n何をお求めでしゅか？\nたこ焼きもありましゅよ！", "ルルィ", -470.0, 0.0, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10031, 6.05, 2, "2025/03/15 15:00:00", 9, "2025/06/23 14:59:59", 8, 2002, 136902, "そのコイン…ピカピカで、\n集めたくなっちゃいましゅ\nタコ釣られされちゃう～…", "ルルィ", -470.0, 0.0, 7);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10032, 0.0, 1, "2025/03/15 15:00:00", 2, "2025/06/23 14:59:59", 8, 2002, 137001, "姫のご友人ならば\n礼儀を尽くすのが爺の務め\nさ、望みの物を言いたまえ", "デュラン", -470.0, 0.0, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10033, 0.0, 2, "2025/03/15 15:00:00", 2, "2025/06/23 14:59:59", 8, 2002, 137001, "キャラバンコインではなく\n首で支払って貰えんかのぅ\n…冗談であるぞ？", "デュラン", -470.0, 0.0, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10034, 0.0, 1, "2025/06/16 15:00:00", 2, "2025/09/23 14:59:59", 9, 2002, 135902, "おう\n好きなもん持ってきな", "サツキ", -470.0, 0.0, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10035, 4.935, 2, "2025/06/16 15:00:00", 1, "2025/09/23 14:59:59", 9, 2002, 135902, "宵越しの銭を持つような\n野暮いマネぁしくさんな\nツキが落ちてもしらねぇぜ", "サツキ", -470.0, 0.0, 6);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10036, 7.441, 1, "2025/06/16 15:00:00", 2, "2025/09/23 14:59:59", 9, 2002, 135802, "ら、ら、らっしゃっせ…\nなんかほしいもん、ある？\nか、かき氷とか、ど…？", "ユキノ", -470.0, 0.0, 5);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10037, 0.0, 2, "2025/06/16 15:00:00", 7, "2025/09/23 14:59:59", 9, 2002, 135802, "そ、そんな見ねぇで…\nあては、売りもんじゃ\nねぇよ…？", "ユキノ", -470.0, 0.0, 7);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10038, 2.295, 1, "2025/09/16 15:00:00", 2, "2025/12/22 14:59:59", 10, 2002, 130901, "クルルをお求めですかっ？\nそれならお礼に、こちらの\n宝石もどうぞですよ～♪", "クルル", -470.0, 0.0, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10039, 6.281, 2, "2025/09/16 15:00:00", 1, "2025/12/22 14:59:59", 10, 2002, 130901, "はっ！　ヒーローさんから\nお代なんて頂けないです！\nどうぞどうぞ…え、ダメ？", "クルル", -470.0, 0.0, 6);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10040, 5.549, 1, "2025/09/16 15:00:00", 2, "2025/12/22 14:59:59", 10, 2002, 137701, "よぅ！　今日の俺さまは\n門番じゃなく、店番だぜ\nメモピ～スフィア～てな！", "ヴォルガーノ", -470.0, 0.0, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10041, 2.64, 2, "2025/09/16 15:00:00", 3, "2025/12/22 14:59:59", 10, 2002, 137701, "…リマさんのブロマイド？\n買い取るに決まってらぁ！\nなんでも持ってけ泥棒っ！", "ヴォルガーノ", -470.0, 0.0, 6);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10042, 7.642, 1, "2025/12/15 15:00:00", 7, "2026/03/23 11:59:59", 11, 2002, 132801, "こ、この格好は…ヴルムが\n集客効果があると言って…\n…本当でしょうか？", "ライラエル", -470.0, 0.0, 4);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10043, 0.0, 2, "2025/12/15 15:00:00", 1, "2026/03/23 11:59:59", 11, 2002, 132802, "この我に店番させるとは…\n全て買わねば許さぬぞ\n我が国庫に貢献するが良い", "ライラエル", -470.0, 0.0, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10044, 0.0, 1, "2025/12/15 15:00:00", 1, "2026/03/23 11:59:59", 11, 2002, 134502, "アナライズっ！\n本日のオススメ商品は～…\nこちらですっ♪", "クローチェ", -470.0, 0.0, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10045, 3.72, 2, "2025/12/15 15:00:00", 2, "2026/03/23 11:59:59", 11, 2002, 134501, "ギガンティックローチェ、\nおひとついかがですかっ？\n格納庫用意して下さいねっ", "クローチェ", -470.0, 0.0, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10046, 4.991, 1, "2026/03/16 12:00:00", 2, "2026/06/22 11:59:59", 12, 2002, 138201, "番頭も、飯事の如き営み\nなれば。愛らしき稚児らで\n千客万来といきませぬか喃", "ネフィ＝ネラ", -470.0, 0.0, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10047, 3.877, 2, "2026/03/16 12:00:00", 1, "2026/06/22 11:59:59", 12, 2002, 138201, "国を営むに金子は必須也…\nどうか御恵みくだしゃんせ\n誠心を以て報恩致しまする", "ネフィ＝ネラ", -470.0, 0.0, 4);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10048, 1.71, 1, "2026/03/16 12:00:00", 4, "2026/06/22 11:59:59", 12, 2002, 136001, "あぅっ…！　天井が低くて\n頭をぶつけてしまって…\nわたしが、大きいだけ…？", "アラクネ", -470.0, 0.0, 6);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10049, 5.32, 2, "2026/03/16 12:00:00", 5, "2026/06/22 11:59:59", 12, 2002, 136001, "いらっしゃいませ騎士さま\nくつろいでいって下さいね\nもし叶うなら…永遠に…", "アラクネ", -470.0, 0.0, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10050, 3.727, 1, "2026/06/15 12:00:00", 9, "2026/09/22 11:59:59", 13, 2002, 135401, "水着で、店番とか──\n本当、意味がわかりません\n海の家でもないのに…", "アネモネ", -470.0, 0.0, 4);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10051, 7.213, 2, "2026/06/15 12:00:00", 7, "2026/09/22 11:59:59", 13, 2002, 135401, "──リアみたいに、\nもっと愛想良い接客を…\nいえ──なんでもないです", "アネモネ", -470.0, 0.0, 9);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10052, 1.874, 1, "2026/06/15 12:00:00", 1, "2026/09/22 11:59:59", 13, 2002, 135301, "いらっしゃいませー♪\n奉仕活動兼、将来のために\nたくさん働いちゃいます♪", "クリア", -470.0, 0.0, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10053, 0.0, 2, "2026/06/15 12:00:00", 2, "2026/09/22 11:59:59", 13, 2002, 135301, "アルバイトが終わったら\n海に遊びに行きましょう！\nモネちゃんも一緒に♪", "クリア", -470.0, 0.0, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10054, 4.215, 1, "2026/09/15 12:00:00", 2, "2026/12/22 11:59:59", 14, 2002, 138001, "大いなる命、神なる勇魚…\n慈しみの矜持を胸に素敵な\n商品をお売りいたします", "ヴァイオレット", -470.0, 0.0, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10055, 0.0, 2, "2026/09/15 12:00:00", 4, "2026/12/22 11:59:59", 14, 2002, 138001, "すみません、わたくしの\n手料理は売り切れなのです\nグレイスが、買い占めを…", "ヴァイオレット", -470.0, 0.0, 4);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10056, 5.477, 1, "2026/09/15 12:00:00", 6, "2026/12/22 11:59:59", 14, 2002, 138901, "何故かいかがわしいお店と\n勘違いされるんですよね\n騎士氏も？　ヤダへんふし", "グレイス", -470.0, 0.0, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10057, 5.743, 2, "2026/09/15 12:00:00", 2, "2026/12/22 11:59:59", 14, 2002, 138901, "どうも。グレイスちゃん\n客寄せバージョンですぴょん\n一名様ごあんな～い", "グレイス", -470.0, 0.0, 1);
